public static string Apply(string text)
{
    if (string.IsNullOrWhiteSpace(text)) return text;
    int search_from = 0;
    for (int guard = 0; guard < 12 && search_from <= text.Length; guard++)
    {
        var m = Cue.Match(text, search_from);
        if (!m.Success) break;
        string? fixedText = TryCorrect(text, m);
        if (fixedText == null)
        {
            search_from = m.Index + m.Length; // ordinary speech; look further on
            continue;
        }
        text = fixedText;
        search_from = 0;
    }
    return text;
}
